import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /**
     * A grade's rate as the screen shows it; the percent always carries two decimals, and the from-date is null for a
     * rate that applies from the beginning of time; the to-date is null for a rate with no end. The version is the
     * number of versions the rate has (its newest, the one shown, counting from 1).
     */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to, int version) {
        static RateView of(Rate r) {
            return new RateView(r.getGrade(), r.getPct().toPlainString(), r.getFrom(), r.getTo(), r.getVersion());
        }
    }

    /**
     * A rate as the form submits it: a percent of 0.00 or more with up to two decimals, an optional from-date and an
     * optional to-date not before it.
     */
    public record RateForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal pct,
            LocalDate from, LocalDate to) {

        @AssertTrue(message = "The to-date must not be before the from-date.")
        public boolean isToNotBeforeFrom() {
            return to == null || from == null || !to.isBefore(from);
        }
    }

    /** A candidate percent to preview: 0.00 or more with up to two decimals. */
    public record PreviewForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal pct) {
    }

    /** How many claims would show a different due, and the sum of the differences, with two decimals. */
    public record PreviewView(int count, String diff) {
    }

    /** The import box: lines of grade,rate,from,to. */
    public record ImportForm(@NotNull @Size(max = 100_000) String text) {
    }

    private final RateService service;
    private final RateImportService imports;
    private final ClaimService claims;

    public RateController(RateService service, RateImportService imports, ClaimService claims) {
        this.service = service;
        this.imports = imports;
        this.claims = claims;
    }

    /** The rates set on the sheet, by grade and from-date; a grade with no rate is left out. */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    /**
     * The rates that apply on the sheet, by grade and from-date: its own, and for a date on which a grade has none in
     * force, its parent sheets' (see {@link RateChain}); a grade with no rate is left out.
     */
    @GetMapping("/applying")
    public List<RateView> applying(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.applying(sheetId).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody RateForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return RateView.of(service.set(user, sheetId, grade, form.from(), form.to(), form.pct()));
    }

    /** Sets a rate for each line of the import box, in order, all of them or none; the rates set, in line order. */
    @PostMapping("/import")
    public List<RateView> importRates(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ImportForm form, @SessionAttribute(SessionController.USER) String user) {
        return imports.importRates(user, sheetId, form.text()).stream().map(RateView::of).toList();
    }

    /** Previews the grade's rate at a candidate percent on every date; nothing is saved or audited, so a viewer may too. */
    @ViewerPasses
    @PostMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody PreviewForm form) {
        ClaimService.RatePreview p = claims.previewRate(sheetId, grade, form.pct());
        return new PreviewView(p.count(), p.diff().toPlainString());
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Sets a rate for each pasted line of grade,rate,from,to (the last two may be absent or blank), all of them or none. */
@Service
public class RateImportService {

    /** A pasted line read into the rate form's fields. */
    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private final RateService rates;

    public RateImportService(RateService rates) {
        this.rates = rates;
    }

    /**
     * Reads every line first by the rate form's rules, then sets each in line order as the form would, replacing a
     * rate for the same grade and from-date. One change: any line refused refuses them all, and nothing is stored or
     * audited.
     */
    @Transactional
    public List<Rate> importRates(String by, String sheetId, String text) {
        List<Line> lines = new ArrayList<>();
        int n = 0;
        for (String raw : text.split("\\r?\\n")) {
            n++;
            if (!raw.isBlank()) {
                lines.add(read(n, raw));
            }
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of grade,rate,from,to.");
        }
        List<Rate> set = new ArrayList<>();
        for (Line l : lines) {
            set.add(rates.set(by, sheetId, l.grade(), l.from(), l.to(), l.pct()));
        }
        return set;
    }

    private Line read(int n, String raw) {
        String[] f = raw.split(",", -1);
        if (f.length < 2) {
            throw refused("Line " + n + " needs at least a grade and a rate.");
        }
        if (f.length > 4) {
            throw refused("Line " + n + " has more than grade,rate,from,to.");
        }
        String grade = f[0].strip();
        if (!grade.matches("[ABC]")) {
            throw refused("Line " + n + " has a grade that is not A, B or C.");
        }
        String pct = f[1].strip();
        if (!pct.matches("\\d{1,5}(\\.\\d{1,2})?")) {
            throw refused("Line " + n + " has a rate that is not 0.00 or more with up to two decimals.");
        }
        LocalDate from = date(n, "from-date", f.length > 2 ? f[2] : "");
        LocalDate to = date(n, "to-date", f.length > 3 ? f[3] : "");
        if (from != null && to != null && to.isBefore(from)) {
            throw refused("Line " + n + " has a to-date before its from-date.");
        }
        return new Line(grade, new BigDecimal(pct), from, to);
    }

    private static LocalDate date(int n, String what, String raw) {
        String text = raw.strip();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw refused("Line " + n + " has a " + what + " that is not yyyy-mm-dd.");
        }
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.TreeSet;

/**
 * A rate for a grade on a sheet: a percent with two decimals, 0.00 or more, applying from its from-date (null: from
 * the beginning of time) through its to-date (null: with no end).
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    /** The number of this, the newest version, counting from 1; the older ones are kept as {@link RateVersion}s. */
    @Column(name = "version", nullable = false)
    private int version = 1;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public int getVersion() {
        return version;
    }

    /** Replaces this version with a newer one of the percent and to-date; the caller keeps the one replaced. */
    public void newVersion(BigDecimal pct, LocalDate to) {
        this.version++;
        this.pct = pct;
        this.to = to;
    }

    /**
     * The rate in force on the date among one grade's rates: the one with the latest from-date on or before it, unless
     * the date is past that one's to-date; null with none.
     */
    public static Rate inForce(Collection<Rate> rates, LocalDate date) {
        Rate best = rates.stream().filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom,
                        Comparator.nullsFirst(Comparator.naturalOrder())))
                .orElse(null);
        return best == null || (best.getTo() != null && best.getTo().isBefore(date)) ? null : best;
    }

    /**
     * One grade's rates as they apply through a chain of sheets: on each date, the rate the first level has in force
     * then (the sheet's own, then its parent's, and so on). Given as rates that do not overlap, so the one in force on
     * a date among them is the one the chain has; with one level, its rates as they are. Not to be saved.
     */
    public static List<Rate> chained(String sheetId, String grade, List<? extends Collection<Rate>> levels) {
        if (levels.size() == 1) {
            return List.copyOf(levels.get(0));
        }
        // the chain's rate can only change on a from-date, or the day after a to-date
        TreeSet<LocalDate> starts = new TreeSet<>();
        starts.add(LocalDate.MIN);
        for (Collection<Rate> level : levels) {
            for (Rate r : level) {
                if (r.getFrom() != null) {
                    starts.add(r.getFrom());
                }
                if (r.getTo() != null && r.getTo().isBefore(LocalDate.MAX)) {
                    starts.add(r.getTo().plusDays(1));
                }
            }
        }
        List<Rate> chained = new ArrayList<>();
        Rate last = null;
        for (LocalDate start : starts) {
            BigDecimal pct = levels.stream().map(level -> inForce(level, start)).filter(Objects::nonNull)
                    .map(Rate::getPct).findFirst().orElse(null);
            LocalDate end = starts.higher(start) == null ? null : starts.higher(start).minusDays(1);
            if (pct == null) {
                last = null;
            } else if (last != null && last.getPct().compareTo(pct) == 0) {
                last.setTo(end);
            } else {
                last = new Rate(sheetId, grade, start.equals(LocalDate.MIN) ? null : start, pct);
                last.setTo(end);
                chained.add(last);
            }
        }
        return chained;
    }
}
